void mainImage( out vec4 fragColor, in vec2 fragCoord )

{

    vec2 uv = fragCoord.xy / iResolution.xy;

    uv.x *= iResolution.x / iResolution.y;

    // diagonal movement

    vec2 offset = vec2(0.03 * iTime, 0.03 * iTime);

    uv += offset;

    // Rotation

    float angle = 4.0 / 4.0; 

    mat2 rotationMatrix = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

    uv = rotationMatrix * (uv - 0.5) + 0.5;  // girato

    vec2 gridPos = fract(uv / 0.18);

    vec2 center = vec2(0.5);

    // inside out

    float isDarkSquare = step(abs(gridPos.x - center.x), 0.5) * step(abs(gridPos.y - center.y), 0.5);

    // Color del fondo y de los cuadrados

    vec3 backgroundColor = vec3(0.02, 0.02, 0.03); // dark back

    vec3 darkSquareColor = vec3(0.1, 0.1, 0.15);   // dark square

    vec3 lightSquareColor = vec3(0.3, 0.3, 0.35);  // clear square

    // Alternate

    float checkerboard = mod(floor(gridPos.x / 0.5) + floor(gridPos.y / 0.5), 2.0);

    vec3 color = mix(darkSquareColor, lightSquareColor, checkerboard);

    // Dark square

    color = mix(backgroundColor, color, isDarkSquare);

    // Vignette

    float dist = distance(fragCoord.xy, iResolution.xy * 0.5) / max(iResolution.x, iResolution.y);

    float vignette = smoothstep(0.0, 0.4, dist); // start end

    color = mix(color, backgroundColor, vignette * 0.8); 

    fragColor = vec4(color, 1.0);

// it works :D

}
